class SpanKind(str, Enum):
    """Observation kind. Values are OpenInference ``openinference.span.kind`` values.

    - ``AGENT``: an agent invocation or run
    - ``LLM``: a model call (generations use this)
    - ``TOOL``: a tool execution
    - ``RETRIEVER``: a retrieval / search step
    - ``EMBEDDING``: an embedding computation
    - ``RERANKER``: a reranking step, e.g. reordering retrieved documents by relevance
    - ``CHAIN``: a generic processing step (the default)
    """

    AGENT = "AGENT"
    LLM = "LLM"
    TOOL = "TOOL"
    RETRIEVER = "RETRIEVER"
    EMBEDDING = "EMBEDDING"
    RERANKER = "RERANKER"
    CHAIN = "CHAIN"


# SpanKind -> OTel GenAI gen_ai.operation.name, where a canonical operation exists.
# CHAIN is deliberately absent: the conventions define no operation for a
# generic workflow step, and inventing one would put a non-spec value in a
# spec-defined enum. Revisit only if the upstream invoke_node proposal lands.
# RERANKER maps to rerank, which the conventions do not define either. It is
# the value the Vercel AI SDK's @ai-sdk/otel writes on a rerank call, and the
# SDKs write it on AI SDK v6 reranks too, so it is already on the wire. Mapping
# the kind to it gives every rerank span (AI SDK, OpenInference RERANKER,
# user-created) the same operation, so a filter on either key finds them all.
_OPERATION_BY_KIND: dict[SpanKind, str] = {
    SpanKind.LLM: "chat",
    SpanKind.TOOL: "execute_tool",
    SpanKind.EMBEDDING: "embeddings",
    SpanKind.AGENT: "invoke_agent",
    SpanKind.RETRIEVER: "retrieval",
    SpanKind.RERANKER: "rerank",
}

# The inverse, for spans that speak the conventions (and the GenAI-native
# vendor operations listed below, such as agent_step and rerank). A
# GenAI-native instrumentation sets gen_ai.operation.name and never heard of
# openinference.span.kind, and both keys must be present on every span, so
# the derivation has to run in both directions.
#
# Not a mechanical inversion of the map above, and it cannot be generated from
# it, for two reasons:
#   - several operations share one kind. text_completion and generate_content
#     are LLM calls the same way chat is, and create_agent is an AGENT span
#     just as invoke_agent is, so the mapping is many-to-one and only the
#     chat/invoke_agent entries round-trip.
#   - CHAIN has no operation of its own, but three operations land on it.
#     invoke_workflow and plan are real GenAI operations with no taxonomy
#     value of their own; CHAIN is the honest home for both, and the reverse
#     direction is the only one that can say so. agent_step is not a
#     conventions operation: the Vercel AI SDK's @ai-sdk/otel writes it on
#     each step of an agent run (one model call and the tools it asked
#     for), a step within the run rather than an agent invocation, so
#     CHAIN as well.
#   - LLM also takes four operations @ai-sdk/otel writes that no convention
#     defines, kept as written rather than rewritten to chat or given an
#     invented name: decide (the experimental decision call: an operation
#     span and its model call, both a billed call to a decision model, so
#     LLM rather than CHAIN, which would hide the call), and the AI SDK's
#     own operation ids for speech and transcription (ai.generateSpeech,
#     ai.transcribe, ai.streamTranscribe), each one call to a remote audio
#     model. OpenInference has no audio kind, and LLM is its model call.
_KIND_BY_OPERATION: dict[str, SpanKind] = {
    "chat": SpanKind.LLM,
    "text_completion": SpanKind.LLM,
    "generate_content": SpanKind.LLM,
    "execute_tool": SpanKind.TOOL,
    "embeddings": SpanKind.EMBEDDING,
    "invoke_agent": SpanKind.AGENT,
    "create_agent": SpanKind.AGENT,
    "retrieval": SpanKind.RETRIEVER,
    "rerank": SpanKind.RERANKER,
    "invoke_workflow": SpanKind.CHAIN,
    "plan": SpanKind.CHAIN,
    "agent_step": SpanKind.CHAIN,
    "decide": SpanKind.LLM,
    "ai.generateSpeech": SpanKind.LLM,
    "ai.transcribe": SpanKind.LLM,
    "ai.streamTranscribe": SpanKind.LLM,
}

# SpanKind (our taxonomy ATTRIBUTE) -> the OpenTelemetry SpanKind FIELD, set
# centrally at span creation. The GenAI conventions decide the field per
# operation: inference, embeddings and retrieval call out of the process
# (CLIENT); execute_tool is INTERNAL; invoke_agent is CLIENT only for a hosted
# agent. Hence:
# - LLM / EMBEDDING / RETRIEVER / RERANKER -> CLIENT: a remote model or
#   index is called.
# - TOOL -> INTERNAL: a bare TOOL span is an in-process function, and the
#   execute-tool convention says INTERNAL. The MCP wrapper overrides this to
#   CLIENT at its own call site because a tools/call crosses a process
#   boundary and the MCP client convention says CLIENT.
# - AGENT -> INTERNAL: an observed agent function is an in-process agent, the
#   convention's INTERNAL case; a hosted agent would need a call-site override.
# - CHAIN -> INTERNAL: a workflow step by definition.
# Nothing in the backend groups on this field (it reads the attributes), so
# the mapping is free to follow the conventions exactly.
# Python holds the kind's NAME ("CLIENT"), so the generated module imports
# nothing and a producer without the OpenTelemetry SDK can vendor it: the SDK
# turns a name into the enum with OtelSpanKind[name], and a producer writing
# OTLP itself maps it to the wire's numbering, which differs from the API's.
_OTEL_KIND_BY_KIND: dict[SpanKind, str] = {
    SpanKind.LLM: "CLIENT",
    SpanKind.EMBEDDING: "CLIENT",
    SpanKind.RETRIEVER: "CLIENT",
    SpanKind.RERANKER: "CLIENT",
    SpanKind.TOOL: "INTERNAL",
    SpanKind.AGENT: "INTERNAL",
    SpanKind.CHAIN: "INTERNAL",
}

# Which attribute names the target of a span's `{operation} {target}` name,
# per kind. One key each, so a tool name can never surface in an agent's name
# and the composed name stays a reliable filter value. CHAIN is absent: it has
# no operation and so no composed name. LLM reads the REQUEST model on
# purpose: a pending snapshot must carry the same name as the final span.
# RERANKER reads the request model too, as EMBEDDING does, so a rerank span
# is named `rerank <model>`.
_NAME_TARGET_BY_KIND: dict[SpanKind, str] = {
    SpanKind.LLM: GEN_AI_REQUEST_MODEL,
    SpanKind.EMBEDDING: GEN_AI_REQUEST_MODEL,
    SpanKind.TOOL: GEN_AI_TOOL_NAME,
    SpanKind.AGENT: GEN_AI_AGENT_NAME,
    SpanKind.RETRIEVER: GEN_AI_DATA_SOURCE_ID,
    SpanKind.RERANKER: GEN_AI_REQUEST_MODEL,
}

